<?php
require_once dirname(__DIR__,3).'/core/Session/AsiloSession.php'; require_once dirname(__DIR__,3).'/core/Security/CsrfToken.php'; require_once dirname(__DIR__,3).'/infra/Database/Database.php'; require_once dirname(__DIR__,3).'/presentation/layout/AsiloView.php'; require_once dirname(__DIR__,2).'/autenticacao/services/AsiloAutenticacaoService.php'; require_once dirname(__DIR__,2).'/usuarios/repository/AsiloUsuarioRepository.php';
final class AsiloCompraController { private AsiloSession $s; private PDO $pdo; private array $u; public function __construct(){ $this->s=new AsiloSession();$this->pdo=PDOMysqli::connection();$u=(new AsiloAutenticacaoService(new AsiloUsuarioRepository($this->pdo),$this->s))->usuarioAtual();if(!$u){header('Location: ?route=login',true,303);exit;}$this->u=$u;if(!in_array($u['perfil'],['Administrador','Almoxarife'],true))$this->deny(); }
 public function listar():void{$q=$this->pdo->query('SELECT sc.id,m.nome material_nome,sc.quantidade,sc.situacao,sc.observacao,sc.solicitada_em,u.nome solicitante FROM solicitacoes_compra sc JOIN materiais m ON m.id=sc.material_id JOIN usuarios u ON u.id=sc.usuario_solicitante_id ORDER BY sc.solicitada_em DESC,sc.id DESC');$this->view('lista.php',['solicitacoes'=>$q->fetchAll()]);}
 public function nova():void{$m=$this->pdo->query('SELECT material_id id,nome,unidade_medida FROM vw_estoque_atual WHERE ativo=1 ORDER BY nome')->fetchAll();$this->view('formulario.php',['materiais'=>$m,'csrfToken'=>CsrfToken::obter('asilosoft_compras')]);}
 public function criar():never{$id=(int)($_POST['material_id']??0);$q=str_replace(',','.',trim((string)($_POST['quantidade']??'')));$obs=trim((string)($_POST['observacao']??''));if($id<1||!is_numeric($q)||(float)$q<=0||$obs===''){$this->s->flash('erro','Informe item, quantidade positiva e justificativa.');$this->go('compras-nova');}$m=$this->pdo->prepare('SELECT id FROM materiais WHERE id=:id AND ativo=1');$m->execute(['id'=>$id]);if(!$m->fetch()){$this->s->flash('erro','Material ativo não encontrado.');$this->go('compras-nova');}$st=$this->pdo->prepare('INSERT INTO solicitacoes_compra (material_id,usuario_solicitante_id,quantidade,observacao) VALUES (:m,:u,:q,:o)');$st->execute(['m'=>$id,'u'=>$this->u['id'],'q'=>$q,'o'=>$obs]);$this->s->flash('sucesso','Solicitação criada como pendente.');$this->go('compras');}
 public function situacao():never{if($this->u['perfil']!=='Administrador')$this->deny();$id=(int)($_GET['id']??0);$situacao=(string)($_POST['situacao']??'');if($id<1||!in_array($situacao,['Aprovada','Recusada','Atendida'],true)){$this->s->flash('erro','Situação inválida.');$this->go('compras');}$q=$this->pdo->prepare('UPDATE solicitacoes_compra SET situacao=:s WHERE id=:id');$q->execute(['s'=>$situacao,'id'=>$id]);$this->s->flash('sucesso','Situação atualizada.');$this->go('compras');}
 private function view(string $f,array $d):void{AsiloView::render(dirname(__DIR__).'/view/'.$f,$d+['titulo'=>'Solicitações de compra','usuarioAtual'=>$this->u,'secaoAtual'=>'almoxarifado','modoDemonstracao'=>false]);}private function go(string $r):never{header('Location: ?route='.$r,true,303);exit;}private function deny():never{http_response_code(403);AsiloView::render(dirname(__DIR__,3).'/presentation/components/asiloAcessoNegado.php',['titulo'=>'Acesso negado','usuarioAtual'=>$this->u,'modoDemonstracao'=>false]);exit;}}
